export async function countComments(
  orgId: OrgId,
  issueId: IssueId,
): Promise<number> {
  // Replies are comments: every non-deleted row on the issue counts, and a
  // soft-deleted row does not, whether or not it still anchors a reply.
  const row = getDb()
    .select({ value: count() })
    .from(comments)
    .where(
      and(
        ...compact(
          orgPredicate(comments.orgId, orgId),
          eq(comments.issueId, issueId),
          shouldFilterArchived() ? isNull(comments.archivedAt) : undefined,
        ),
      ),
    )
    .get();
  return row?.value ?? 0;
}

