const COMMENT_PAGE_SIZE = 100;

/**
 * Removes every comment document that belongs to one issue. Replies are
 * comments of that issue too, so they go with it. Other issues and other
 * workspaces are never addressed: both the list and the delete are scoped by
 * `orgId` and `issueId`.
 */
async function removeIssueCommentsFromIndex(
  orgId: OrgId,
  issueId: IssueId,
): Promise<void> {
  let cursor: string | null = null;
  const seen = new Set<string>();

  for (;;) {
    const page = await commentRepo.listComments({
      orgId,
      issueId,
      limit: COMMENT_PAGE_SIZE,
      cursor,
      includeArchived: true,
    });

    for (const comment of page.items) {
      await removeFromIndex(orgId, "comment", comment.id);
    }

    if (!page.nextCursor || seen.has(page.nextCursor)) break;
    seen.add(page.nextCursor);
    cursor = page.nextCursor;
  }
}

