export async function runSearchReindexJob(orgId: OrgId): Promise<JobResult> {
  return runJob("search-reindex", async (result) => {
    // Replace this workspace's index outright. Upsert alone would leave
    // archived issues and deleted comments in place, and would resurrect them
    // on the next rebuild. Other workspaces are untouched: the delete is
    // scoped to `orgId`, and every read below is too.
    await searchRepo.clearOrgSearchDocuments(orgId);

    await eachPage(
      (cursor) =>
        projectRepo.listProjects({
          orgId,
          limit: PAGE_SIZE,
          cursor,
          includeArchived: false,
        }),
      async (project) => {
        try {
          await indexProject(orgId, project);
          result.processed += 1;
        } catch (error) {
          result.failed += 1;
          logger.error("failed to index project", {
            projectId: project.id,
            reason: error instanceof Error ? error.message : String(error),
          });
        }
      },
    );

    // Live issues only. Comments are listed flat, not via the thread tree, so
    // a live reply whose parent was deleted is still indexed, a deleted
    // comment is not, and a thread longer than one page is walked to the end.
    await eachPage(
      (cursor) =>
        issueRepo.listIssues({
          orgId,
          limit: PAGE_SIZE,
          cursor,
          includeArchived: false,
        }),
      async (issue) => {
        try {
          await indexIssue(orgId, issue);
          result.processed += 1;

          await eachPage(
            (commentCursor) =>
              commentRepo.listComments({
                orgId,
                issueId: issue.id,
                limit: PAGE_SIZE,
                cursor: commentCursor,
                includeArchived: false,
              }),
            async (comment) => {
              await indexComment(orgId, comment);
              result.processed += 1;
            },
          );
        } catch (error) {
          result.failed += 1;
          logger.error("failed to index issue", {
            issueId: issue.id,
            reason: error instanceof Error ? error.message : String(error),
          });
        }
      },
    );
  });
}

/**
 * Walks every page of a cursor listing. Callers cap `limit` at `PAGE_SIZE`,
 * which is also the repository maximum, so a backlog larger than one page is
 * still covered. A repeated cursor stops the walk rather than looping.
 */
async function eachPage<T>(
  load: (cursor: string | null) => Promise<Page<T>>,
  visit: (item: T) => Promise<void>,
): Promise<void> {
  let cursor: string | null = null;
  const seen = new Set<string>();

  for (;;) {
